// Verify X-Signature = HMAC-SHA256(N8N_SHARED_SECRET, raw request body).
const crypto = require('crypto');
const secret = $env.N8N_SHARED_SECRET;
if (!secret) { throw new Error('N8N_SHARED_SECRET is not set'); }
const item = $input.first();
const headers = item.json.headers || {};
const sig = headers['x-signature'] || headers['X-Signature'];
let rawBody = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : (typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body));
const expected = crypto.createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');
if (!sig || expected !== sig) { throw new Error('invalid signature'); }
const payload = typeof item.json.body === 'string' ? JSON.parse(item.json.body) : item.json.body;
return [{ json: payload }];

// Multilingual support auto-reply ("We received your request...").
const p = $input.first().json;
const lang = (p.language || 'en').toLowerCase();
const d = p.data || {};
const ref = d.order_number ? ` (${d.order_number})` : '';

const t = {
  en: { subject: `We received your message${ref}`, body: 'Thanks for contacting Glitchy support. We have received your request and a member of our team will get back to you within 1–2 business days. There is no need to reply to this message.', sign: 'The Glitchy Support Team' },
  it: { subject: `Abbiamo ricevuto il tuo messaggio${ref}`, body: 'Grazie per aver contattato l’assistenza Glitchy. Abbiamo ricevuto la tua richiesta e un membro del nostro team ti risponderà entro 1–2 giorni lavorativi. Non è necessario rispondere a questo messaggio.', sign: 'Il team di assistenza Glitchy' },
  fr: { subject: `Nous avons bien reçu votre message${ref}`, body: 'Merci d’avoir contacté le support Glitchy. Nous avons bien reçu votre demande et un membre de notre équipe vous répondra sous 1 à 2 jours ouvrés. Il est inutile de répondre à ce message.', sign: 'L’équipe support Glitchy' }
}[lang];
const L = t || { subject: `We received your message${ref}`, body: 'Thanks for contacting Glitchy support. We have received your request and a member of our team will get back to you within 1–2 business days.', sign: 'The Glitchy Support Team' };

const subjEcho = d.subject ? `<p style="color:#666"><em>Re: ${d.subject}</em></p>` : '';
const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:auto;color:#222">
<h2 style="color:#111">${L.subject}</h2>
${subjEcho}
<p>${L.body}</p>
<p style="margin-top:20px;color:#666">${L.sign}</p>
</div>`;

return [{ json: { to: p.recipient || d.from_email, subject: L.subject, html } }];
